@Test
public void testBasicSimplification() {
    // this tests that a basic simplification is done by calling the helpers in Expressions. those
    // are more thoroughly tested in TestExpressionHelpers.
    // the second predicate is always true once it is bound because z is an integer and the literal
    // is less than any 32-bit integer value
    Assert.assertEquals("Should simplify or expression to alwaysTrue", alwaysTrue(), Binder.bind(STRUCT, or(lessThan("y", 100), greaterThan("z", -9999999999L))));
    // similarly, the second predicate is always false
    Assert.assertEquals("Should simplify and expression to predicate", alwaysFalse(), Binder.bind(STRUCT, and(lessThan("y", 100), lessThan("z", -9999999999L))));
    Expression bound = Binder.bind(STRUCT, not(not(lessThan("y", 100))));
    BoundPredicate<?> pred = TestHelpers.assertAndUnwrap(bound);
    Assert.assertEquals("Should have the correct bound field", 1, pred.ref().fieldId());
}

@Test
public void testSimplifyOr() {
    Assert.assertEquals("alwaysTrue or pred => alwaysTrue", alwaysTrue(), or(alwaysTrue(), pred));
    Assert.assertEquals("pred or alwaysTrue => alwaysTrue", alwaysTrue(), or(pred, alwaysTrue()));
    Assert.assertEquals("alwaysFalse or pred => pred", pred, or(alwaysFalse(), pred));
    Assert.assertEquals("pred or alwaysTrue => pred", pred, or(pred, alwaysFalse()));
}

@Test
public void testSimplifyAnd() {
    Assert.assertEquals("alwaysTrue and pred => pred", pred, and(alwaysTrue(), pred));
    Assert.assertEquals("pred and alwaysTrue => pred", pred, and(pred, alwaysTrue()));
    Assert.assertEquals("alwaysFalse and pred => alwaysFalse", alwaysFalse(), and(alwaysFalse(), pred));
    Assert.assertEquals("pred and alwaysFalse => alwaysFalse", alwaysFalse(), and(pred, alwaysFalse()));
}

@Test
public void testSimplifyNot() {
    Assert.assertEquals("not(alwaysTrue) => alwaysFalse", alwaysFalse(), not(alwaysTrue()));
    Assert.assertEquals("not(alwaysFalse) => alwaysTrue", alwaysTrue(), not(alwaysFalse()));
    Assert.assertEquals("not(not(pred)) => pred", pred, not(not(pred)));
}

