@Test
public void testIdentityConversions() {
    List<Pair<Literal<?>, Type>> pairs = Arrays.asList(Pair.of(Literal.of(true), Types.BooleanType.get()), Pair.of(Literal.of(34), Types.IntegerType.get()), Pair.of(Literal.of(34L), Types.LongType.get()), Pair.of(Literal.of(34.11F), Types.FloatType.get()), Pair.of(Literal.of(34.55D), Types.DoubleType.get()), Pair.of(Literal.of("34.55"), Types.DecimalType.of(9, 2)), Pair.of(Literal.of("2017-08-18"), Types.DateType.get()), Pair.of(Literal.of("14:21:01.919"), Types.TimeType.withoutZone()), Pair.of(Literal.of("2017-08-18T14:21:01.919"), Types.TimestampType.withoutZone()), Pair.of(Literal.of("abc"), Types.StringType.get()), Pair.of(Literal.of(UUID.randomUUID()), Types.UUIDType.get()), Pair.of(Literal.of(new byte[] { 0, 1, 2 }), Types.FixedType.ofLength(3)), Pair.of(Literal.of(ByteBuffer.wrap(new byte[] { 0, 1, 2 })), Types.BinaryType.get()));
    for (Pair<Literal<?>, Type> pair : pairs) {
        Literal<?> lit = pair.first();
        Type type = pair.second();
        // first, convert the literal to the target type (date/times start as strings)
        Literal<?> expected = lit.to(type);
        // then check that converting again to the same type results in an identical literal
        Assert.assertSame("Converting twice should produce identical values", expected, expected.to(type));
    }
}

@Test
public void testBinaryToFixed() {
    Literal<ByteBuffer> lit = Literal.of(ByteBuffer.wrap(new byte[] { 0, 1, 2 }));
    Literal<ByteBuffer> fixedLit = lit.to(Types.FixedType.ofLength(3));
    Assert.assertNotNull("Should allow conversion to correct fixed length", fixedLit);
    Assert.assertEquals("Conversion should not change value", lit.value().duplicate(), fixedLit.value().duplicate());
    Assert.assertNull("Should not allow conversion to different fixed length", lit.to(Types.FixedType.ofLength(4)));
    Assert.assertNull("Should not allow conversion to different fixed length", lit.to(Types.FixedType.ofLength(2)));
}

