    Assert.assertEquals("Value should match", new BigDecimal("34.56"), lit.to(Types.DecimalType.of(9, 2)).value());
    Assert.assertEquals("Value should match", new BigDecimal("34.5600"), lit.to(Types.DecimalType.of(9, 4)).value());
}

@Test
public void testDecimalToDecimalConversion() {
    Literal<BigDecimal> lit = Literal.of(new BigDecimal("34.11"));
    Assert.assertSame("Should return identical object when converting to same scale", lit, lit.to(Types.DecimalType.of(9, 2)));
    Assert.assertSame("Should return identical object when converting to same scale", lit, lit.to(Types.DecimalType.of(11, 2)));
    Assert.assertNull("Changing decimal scale is not allowed", lit.to(Types.DecimalType.of(9, 0)));
    Assert.assertNull("Changing decimal scale is not allowed", lit.to(Types.DecimalType.of(9, 1)));
    Assert.assertNull("Changing decimal scale is not allowed", lit.to(Types.DecimalType.of(9, 3)));
}

