    Assert.assertEquals("L2 should contain lat", 52.995143f, (float) projectedL2.get("lat"), 0.000001);
    Assert.assertNull("L2 should not contain long", projectedL2.get("long"));
    projected = writeAndRead("long_only", writeSchema, writeSchema.select("locations.long"), record);
    Assert.assertNull("Should not project id", projected.get("id"));
    locations = toStringMap((Map) projected.get("locations"));
    Assert.assertNotNull("Should project locations map", locations);
    Assert.assertEquals("Should contain L1 and L2", Sets.newHashSet("L1", "L2"), locations.keySet());
    projectedL1 = (Record) locations.get("L1");
    Assert.assertNotNull("L1 should not be null", projectedL1);
    Assert.assertNull("L1 should not contain lat", projectedL1.get("lat"));
    Assert.assertEquals("L1 should contain long", -1.542616f, (float) projectedL1.get("long"), 0.000001);
    projectedL2 = (Record) locations.get("L2");
    Assert.assertNotNull("L2 should not be null", projectedL2);
    Assert.assertNull("L2 should not contain lat", projectedL2.get("lat"));
    Assert.assertEquals("L2 should contain long", -1.539054f, (float) projectedL2.get("long"), 0.000001);
    Schema latitiudeRenamed = new Schema(Types.NestedField.optional(5, "locations", Types.MapType.ofOptional(6, 7, Types.StructType.of(Types.NestedField.required(1, "latitude", Types.FloatType.get())))));
    projected = writeAndRead("latitude_renamed", writeSchema, latitiudeRenamed, record);
    Assert.assertNull("Should not project id", projected.get("id"));
    locations = toStringMap((Map) projected.get("locations"));
    Assert.assertNotNull("Should project locations map", locations);
    Assert.assertEquals("Should contain L1 and L2", Sets.newHashSet("L1", "L2"), locations.keySet());
    projectedL1 = (Record) locations.get("L1");
